def test_error_mapping() -> None:
    err = SolvaPayError('boom')
    setattr(err, 'status', 400)
    setattr(err, 'code', 'bad_request')
    assert getattr(err, 'status') == 400
    assert getattr(err, 'code') == 'bad_request'
    paywall = PaywallError(
        'Payment required',
        {
            'kind': 'payment_required',
            'product': 'prd_x',
            'checkoutUrl': 'https://example.com/checkout',
            'message': 'Payment required',
        },
    )
    assert paywall.name == 'PaywallError'
    assert paywall.structured_content['kind'] == 'payment_required'

